// Verified Kalshi KXNCAAF* team code -> Polymarket US cfb abbreviation crosswalk.
//
// Data: ncaaf-crosswalk.json, generated by scripts/gen-ncaaf-crosswalk.js from REAL
// Kalshi events + Polymarket US cfb events (team names AND ET game date must agree;
// see that script for the exact rules). Anything not in the table is UNMAPPED and
// stays that way: no guessing, no even-splitting of the Kalshi team blob.
//
// Canonical NCAAF team identity in this worker = the Polymarket abbreviation
// (lowercase, e.g. "ntx", "oregst"). A Kalshi code is translated to it through the
// table; a Polymarket market is only trusted when its own team.name still equals the
// name recorded here for that abbreviation.
'use strict';
const data = require('./ncaaf-crosswalk.json');

const norm = (s) => String(s || '').toLowerCase().replace(/&/g, ' and ').replace(/\bst\.(?=\s|$)/g, 'state')
  .replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();

const byCode = new Map(); // KALSHI CODE -> { p, name, pname }
const byPoly = new Map(); // poly abbr -> { code, name, pname }
for (const [code, t] of Object.entries(data.teams || {})) {
  if (!/^[A-Z]+$/.test(code) || !/^[a-z0-9]+$/.test(t.p)) continue;
  if (byPoly.has(t.p)) { // defensive: a poly abbr claimed twice is dropped entirely
    byCode.delete(byPoly.get(t.p).code);
    byPoly.set(t.p, null);
    continue;
  }
  if (byPoly.get(t.p) === null) continue;
  byCode.set(code, { p: t.p, name: t.name, pname: t.pname });
  byPoly.set(t.p, { code, p: t.p, name: t.name, pname: t.pname });
}
for (const [p, v] of [...byPoly]) if (v === null) byPoly.delete(p);
const CODES = [...byCode.keys()].sort((a, b) => b.length - a.length);

// "UNTTLSA" -> { codes: ['UNT','TLSA'], pair: ['ntx','tulsa'] } ONLY when exactly one
// way of reading the blob uses two distinct known codes; otherwise null.
function splitBlob(blob) {
  const s = String(blob || '').toUpperCase();
  if (!/^[A-Z]+$/.test(s)) return null;
  const hits = [];
  for (const a of CODES) {
    if (!s.startsWith(a)) continue;
    const r = s.slice(a.length);
    if (r !== a && byCode.has(r)) hits.push([a, r]);
  }
  if (hits.length !== 1) return null;
  const [a, b] = hits[0];
  const ta = byCode.get(a);
  const tb = byCode.get(b);
  if (ta.p === tb.p) return null;
  return { codes: [a, b], pair: [ta.p, tb.p] };
}

// Polymarket renamed a few teams after the crosswalk was generated. Each extra name
// here was checked by hand against the live gateway (team.abbreviation + team.name on
// every cfb market, 2026-10-28: 264 teams, these 2 were the only name changes).
// Keyed by Polymarket abbreviation; the abbreviation itself must still match.
const POLY_NAME_ALIASES = Object.freeze({
  kanst: Object.freeze(['K-State']),
  loutch: Object.freeze(['LA Tech']),
});

/** All names Polymarket may use for this crosswalk team (pname first). */
function polyNames(team) {
  if (!team) return [];
  const extra = (team.p && POLY_NAME_ALIASES[team.p]) || [];
  return [team.pname, ...extra].filter(Boolean);
}

/** Exact (normalized) name match against the team's Polymarket name or a verified alias. */
function polyNameIs(team, name) {
  const n = norm(name);
  return !!n && polyNames(team).some((x) => norm(x) === n);
}

/** Normalized text names the team by its Polymarket name or a verified alias. */
function polyTextNames(team, text) {
  const q = norm(text);
  return !!q && polyNames(team).some((x) => { const n = norm(x); return !!n && q.includes(n); });
}

const teamByCode = (code) => byCode.get(String(code || '').toUpperCase()) || null;
const teamByPoly = (abbr) => byPoly.get(String(abbr || '').toLowerCase()) || null;

// Lock leg "game" text ("Texas St. vs San Diego St.") must name exactly the two
// Kalshi teams the codes resolve to.
function gameNamesAgree(game, codes) {
  if (!game || !Array.isArray(codes) || codes.length !== 2) return false;
  const parts = String(game).split(/\s+vs\.?\s+/i);
  if (parts.length !== 2) return false;
  const want = codes.map((c) => { const t = teamByCode(c); return t ? norm(t.name) : null; });
  if (want.some((w) => !w)) return false;
  const got = parts.map(norm);
  return (got[0] === want[0] && got[1] === want[1]) || (got[0] === want[1] && got[1] === want[0]);
}

module.exports = {
  splitBlob,
  teamByCode,
  teamByPoly,
  gameNamesAgree,
  norm,
  polyNames,
  polyNameIs,
  polyTextNames,
  POLY_NAME_ALIASES,
  generatedAt: data.generatedAt || null,
  teamCount: byCode.size,
  unmatchedKalshi: data.unmatchedKalshi || [],
  unmatchedPoly: data.unmatchedPoly || [],
};
